def WindowAdmissible {m : ℕ} (w : DirectionWord m) (d : Compass) : Prop :=
  d ≠ (windowArrival w).reverse ∧ ∀ i : Fin m,
    wordBond (0, 0) w i ≠
      {wordVertex (0, 0) w m, wordVertex (0, 0) w m + d.step}

def windowKind {m : ℕ} (w : DirectionWord m) (d : Compass) : StepKind :=
  if 0 < departureCount (0, 0) w m (wordVertex (0, 0) w m) then .revisit
  else if d = windowArrival w then .straight else .turn

def memoryBaseConstant (m : ℕ) (q : ℝ) (v : MemoryWindow m → ℝ) : ℝ :=
  max (sSup {r : ℝ | ∃ j < m, r = (openTrailTotal j (0, 0) .east : ℝ) * q ^ (-(j : ℤ))})
    (memoryWitnessRatio v * (openTrailTotal m (0, 0) .east : ℝ) * q ^ (-(m : ℤ)))

def truePhaseCoefficient {n : ℕ} (w : DirectionWord n) (i : Fin n) (φ ψ : Phase) : ℚ :=
  phaseTransition (if wordRevisit kernelStart w i then .revisit
    else if wordStraight kernelIncoming w i then .straight else .turn) (witnessKappa w i) φ ψ

def longOrdering {n : ℕ} (w : DirectionWord n) : List (Fin n) :=
  (firstVisitList w).filter (wordStraight kernelIncoming w) ++
    (firstVisitList w).filter (fun i => !wordStraight kernelIncoming w i)

def truePhaseSuffix {n : ℕ} (w : DirectionWord n) (L : ℕ) (φ : Phase) : ℚ :=
  let p := ((List.finRange n).drop L).foldl (fun p i ψ => ∑ χ : Phase, p χ *
    phaseTransition (if wordRevisit kernelStart w i then .revisit
      else if wordStraight kernelIncoming w i then .straight else .turn) (witnessKappa w i) χ ψ)
    (fun ψ => if ψ = φ then (1 : ℚ) else 0)
  ∑ ψ, p ψ * phaseTerminal ψ

def stationaryContinuationSum (Q : MemoryQuotient 10 3741) (X : PairType) (d₀ : Compass)
    (φ : Phase) (a : Fin 3741) (x : Plane) (R : ℕ) : ℚ :=
  ∑ j ∈ Finset.range (R + 1), ((stationaryApply Q X d₀)^[j]) (stationaryReward X) φ a x

def Network.Ordinary {G : Finset Plane} (D : Network G) : Prop :=
  D.LocalRules ∧ ∀ x ∈ protectedSites G,
    D.status x = .U ∧ D.kept x = neighbours x ∩ G

def Network.spins {G : Finset Plane} (D : Network G)
    (n : (x : D.active) → SpinLetter) (x : Plane) : Vec3 :=
  if h : x ∈ D.active then spinVector (n ⟨x, h⟩) else 0

def Network.expectation {G : Finset Plane} (D : Network G) (τ : PinAssignment G)
    (pinned : Bool) (f : (Plane → Vec3) → ℝ) : ℝ :=
  D.partition τ pinned f / D.partition τ pinned (fun _ => 1)

def traceRatio {G : Finset Plane} (D : Network G) (τ : PinAssignment G)
    (pinned : Bool) (w : List Plane) : ℝ :=
  (traceNetwork D w).partition τ pinned (fun _ => 1) / D.partition τ pinned (fun _ => 1)

def FiniteSpinNetwork.partition {n : ℕ} (D : FiniteSpinNetwork n) (pinned : Bool)
    (f : (Fin n → Vec3) → ℝ) : ℝ :=
  ∑ σ, D.weight pinned σ * f (fun x => spinVector (σ x))

def productDensity (J : Finset (Fin 20)) (u : Fin 20 → Vec3) :
    Matrix (J → Fin 2) (J → Fin 2) ℂ :=
  fun σ τ => ∏ j : J, spinDensity (u j.val) (σ j) (τ j)

def PositiveOn {ι : Type*} [Fintype ι] (S : Submodule ℂ (EuclideanSpace ℂ ι))
    (O : Module.End ℂ (EuclideanSpace ℂ ι)) : Prop :=
  ∀ ψ ∈ S, ψ ≠ 0 → 0 < (inner ℂ ψ (O ψ)).re

def eigenvaluesOn {ι : Type*} [Fintype ι] (S : Submodule ℂ (EuclideanSpace ℂ ι))
    (O : Module.End ℂ (EuclideanSpace ℂ ι)) : Set ℂ :=
  {μ | ∃ ψ ∈ S, ψ ≠ 0 ∧ O ψ = μ • ψ}

def tokenMatrix (J : Finset (Fin 20)) (j : J) (A : Matrix (Fin 2) (Fin 2) ℂ) :
    Matrix (J → Fin 2) (J → Fin 2) ℂ :=
  fun σ τ => if ∀ k, k ≠ j → σ k = τ k then A (σ j) (τ j) else 0

def centralSpace (π : PatternData) (r : Representation) (ε : ExchangeSigns π) :
    Submodule ℂ (EuclideanSpace ℂ (reductionVectors π r → Fin 2)) :=
  exchangeSpace π r ε ⊓ Module.End.eigenspace (totalSpinZ (reductionVectors π r)) (centralWeight π r : ℂ)

def momentLawFunctional {n : ℕ} (F : FrameData n) (s : Status) (f : Vec3 → ℝ) : ℝ :=
  if s = .D then (3 / 5) * (∑ j, F.weight j * f (F.point j)) + (2 / 5) * f 0
  else ∑ j, F.weight j * f (F.point j)

def ProperTorusColouring {L N : AKLT.Challenge.Size}
    (κ : AKLT.Challenge.Site L N → Fin 3) : Prop :=
  ∀ e : AKLT.Challenge.Bond L N, κ e.1 ≠ κ (AKLT.Challenge.nextSite e.1 e.2)

def planeMarginal (κ : Plane → Fin 3) (W B : Finset Plane) (η : FrameBoundary W) :
    Weight (PlaneConfiguration B) :=
  marginal (planeLaw κ W η) (fun σ x => extendLetters σ x.val)

def frameEval {L N : AKLT.Challenge.Size} (κ : AKLT.Challenge.Site L N → Fin 3)
    (ψ : AKLT.Challenge.Hilbert L N) (σ : TorusConfiguration L N) : ℂ :=
  physicalEval ψ (fun x => frameSpinor (κ x) (σ x))

def square (a : Plane) (u : ℕ) : Finset Plane :=
  (Finset.Icc (a.1 - (u : ℤ)) (a.1 + u)).product
    (Finset.Icc (a.2 - (u : ℤ)) (a.2 + u))

def responseNeighbours {n : ℕ} (w : DirectionWord n) (i : Fin n) : Finset Plane :=
  (neighbours (wordVertex kernelStart w i.val)).erase
    (wordVertex kernelStart w i.val - (wordIncoming kernelIncoming w i).step)

def responseKappa {n : ℕ} (X Y : PairType) (s : ℕ) (w : DirectionWord n) (i : Fin n) : ℚ :=
  ∑ p ∈ responsePairs w i,
    if responsePairType p = Y ∧ pairShift X p = s then pairCoefficient w i p else 0

def shortOrderLE {n : ℕ} (w : DirectionWord n) (i j : Fin n) : Bool :=
  let ki := witnessKappa w i
  let kj := witnessKappa w j
  let xi := passageFactor (wordStraight kernelIncoming w i)
  let xj := passageFactor (wordStraight kernelIncoming w j)
  if ki = 0 then decide (kj = 0 ∧ i.val ≤ j.val)
  else if kj = 0 then true else
    let si := (xi - 1) / (xi * ki)
    let sj := (xj - 1) / (xj * kj)
    decide (si < sj ∨ (si = sj ∧ i.val ≤ j.val))

def reductionVectors (π : PatternData) (r : Representation) : Finset (Fin 20) :=
  (reductionGroups π).biUnion fun x =>
    if groupIsPair π r x then {groupLeader x, groupSecond x} else {groupLeader x}

def leafNeighbour (π : PatternData) (x : Plane) : Plane :=
  ((π.bonds.toList.filterMap fun e =>
    if e.1 = x then some e.2 else if e.2 = x then some e.1 else none).headD (0, 0))

def reducedDifference (π : PatternData) (r : Representation) (c : ℚ) :
    MvPolynomial (Fin 20 × Fin 3) ℚ :=
  reducedPolynomial π r false - MvPolynomial.C c * reducedPolynomial π r true

def GroupInversion (π : PatternData) (r : Representation) (I : Finset (Fin 20)) : Prop :=
  I ⊆ reductionVectors π r ∧ ∀ x ∈ reductionGroups π, groupIsPair π r x = true →
    (groupLeader x ∈ I ↔ groupSecond x ∈ I)

def pauliExponent (J : Finset (Fin 20)) (a : J → Fin 4) : (Fin 20 × Fin 3) →₀ ℕ :=
  Finsupp.equivFunOnFinite.symm fun v =>
    if h : v.1 ∈ J then if (a ⟨v.1, h⟩).val = v.2.val + 1 then 1 else 0 else 0

def GroupBasis (π : PatternData) (r : Representation) (ε : ExchangeSigns π)
    (x : reductionGroups π) : Type :=
  Fin (if groupIsPair π r x.val then if π.statusAt x.val = .D ∧ ε x = false then 1 else 3 else 2)

def exchangeWeight (π : PatternData) (r : Representation) (ε : ExchangeSigns π)
    (b : ExchangeBasis π r ε) : ℚ :=
  ∑ x : reductionGroups π,
    if groupIsPair π r x.val then
      if π.statusAt x.val = .D ∧ ε x = false then 0 else 1 - ((b x).val : ℚ)
    else 1 / 2 - ((b x).val : ℚ)

def ClearsDenominator (π : PatternData) (r : Representation) (D₀ : ℕ) : Prop :=
  0 < D₀ ∧ ∀ next : Bool, ∀ m ∈ (reducedPolynomial π r next).support,
    ∃ z : ℤ, ((if next then 5 else 3) * (D₀ : ℚ) * (reducedPolynomial π r next).coeff m) = z

def originalPatternPolynomial (π : PatternData) (next : Bool) : MvPolynomial (Fin 20 × Fin 3) ℚ :=
  contractSpins π.active (fun x => if next ∧ x = (0, 0) then .D else π.statusAt x)
    ((∏ e ∈ π.bonds, if next ∧ ({e.1, e.2} : Finset Plane) = {(0, 0), π.outgoing.step} then 1
      else 1 + formalDot (fun k => .inl (e.1, k)) (fun k => .inl (e.2, k))) *
    ∏ j : Fin 20, if π.statusAt (externalSlot j).1 = .X then 1
      else 1 + formalDot (fun k => .inl ((externalSlot j).1, k)) (fun k => .inr (j, k)))

def exchangeOperator (J : Finset (Fin 20)) (j k : J) :
    Module.End ℂ (EuclideanSpace ℂ (J → Fin 2)) :=
  Matrix.toEuclideanLin fun σ τ => if σ = fun x => τ (Equiv.swap j k x) then 1 else 0

def symmetricPairProjection (J : Finset (Fin 20)) (j k : J) :
    Module.End ℂ (EuclideanSpace ℂ (J → Fin 2)) :=
  (1 / 2 : ℂ) • (1 + exchangeOperator J j k)

def leadingMinor {n : ℕ} (M : Matrix (Fin n) (Fin n) ℤ) (k : ℕ) (h : k ≤ n) : ℤ :=
  (M.submatrix (fun i : Fin k => (⟨i.val, by omega⟩ : Fin n))
    (fun i : Fin k => (⟨i.val, by omega⟩ : Fin n))).det

def binaryPolynomial (d : ℕ) (p : BinaryForm d) : MvPolynomial (Fin 2) ℂ :=
  ∑ j, MvPolynomial.C (p j) * MvPolynomial.X 0 ^ (d - j.val) *
    MvPolynomial.X 1 ^ j.val

def polynomialState {L N : Size} (p : SpinorPolynomial L N) : Hilbert L N :=
  WithLp.toLp 2 fun σ => p.coeff (monomialDegree σ) /
    ∏ x : Site L N, (Real.sqrt (Nat.choose 4 (σ x).val : ℝ) : ℂ)

def logMeanLower (s : ℚ) : ℚ :=
  let t := (1 - s) / (1 + s)
  2 / (1 - s) * ∑ k ∈ Finset.range 8, t ^ (2 * k + 1) / (2 * k + 1 : ℚ)

def logMeanUpper (s : ℚ) : ℚ :=
  let t := (1 - s) / (1 + s)
  logMeanLower s + 2 * t^17 / (17 * (1 - t^2) * (1 - s))

def removedPairMean {G : Finset Plane} (D : Network G) (τ : PinAssignment G)
    (pinned : Bool) (y a b : Plane) : ℝ :=
  (removeSite D y).expectation τ pinned (fun n => dot (n a) (n b))

def responseBeta {G : Finset Plane} (D : Network G) (τ : PinAssignment G)
    (y o f g : Plane) : ℝ :=
  1 / (3 * logarithmicMean (responseI D τ true y o f g) (responseI D τ false y o f g))

def responseAlpha {G : Finset Plane} (D : Network G) (τ : PinAssignment G)
    (y o f g : Plane) : ℝ := responseBeta D τ y o f g -
      1 / (5 * logarithmicMean (responseJ D τ true y f g) (responseJ D τ false y f g))

def responseBetaPrime {G : Finset Plane} (D : Network G) (τ : PinAssignment G)
    (y o f : Plane) : ℝ := 1 / (3 * logarithmicMean
      (1 + removedPairMean D τ true y f o / 3) (1 + removedPairMean D τ false y f o / 3))

def normalizeRotation (a : Compass) (z : Plane) : Plane :=
  match a with
  | .north => z | .east => (z.2, -z.1) | .south => (-z.1, -z.2) | .west => (-z.2, z.1)

def inducedBoundary (W V : Finset Plane) (η : FrameBoundary W) (σ : PlaneConfiguration W) :
    FrameBoundary V :=
  fun z => if z.val ∈ W then extendLetters σ z.val else extendBoundary η z.val

def relaxedReward (x : Plane) (incoming outgoing : Compass) (dead : Finset Plane) : ℚ :=
  let o := x + outgoing.step
  let live := ((neighbours x).erase (x - incoming.step) |>.erase o) \ dead
  ∑ p ∈ (insert o live).powersetCard 2,
    (if o ∈ p then
      if live.card = 1 then betaPrimeBound (decide (outgoing = incoming))
      else betaBound (decide (outgoing = incoming))
    else alphaBound (decide (outgoing = incoming))) * kernelWitness (responsePairType p)

def freeCoefficient {m q : ℕ} (Q : MemoryQuotient m q)
    (φ : Phase) (a : Fin q) (d : Compass) (ψ : Phase) : ℚ :=
  if Q.allowed a d then phaseTransition (Q.kind a d)
    (relaxedReward (0, 0) (Q.arrival a) d ∅) φ ψ else 0

def freeApply {m q : ℕ} (Q : MemoryQuotient m q) (z : Phase → Fin q → ℚ)
    (φ : Phase) (a : Fin q) : ℚ :=
  ∑ d : Compass, ∑ ψ : Phase, freeCoefficient Q φ a d ψ * z ψ (Q.successor a d)

def StationaryData.potential {q : ℕ} (C : StationaryData q)
    (φ : Phase) (a : Fin q) (x : Plane) : ℚ :=
  (C.extended φ a x : ℚ) / certificateValueScale

def prefixPhases {n : ℕ} (w : DirectionWord n) : Phase → ℚ :=
  (List.finRange n).foldl (fun p i ψ => ∑ φ : Phase, p φ *
    phaseTransition (if wordRevisit kernelStart w i then .revisit
      else if wordStraight kernelIncoming w i then .straight else .turn) (witnessKappa w i) φ ψ)
    phaseInitial

def SurvivingPrefix {n : ℕ} (X : PairType) (d₀ : Compass) (w : DirectionWord n) : Prop :=
  IsTrail kernelStart kernelIncoming w ∧ FirstDirection w d₀ ∧
  ∀ j ≤ n, wordVertex kernelStart w j ≠ kernelCentre ∧ wordVertex kernelStart w j ≠ kernelTarget X

def ThreeFactorMeanStatement : Prop :=
  (∀ k : ℕ, k ≤ 3 → ∀ a : Fin k → Vec3, (∀ j, normSq (a j) ≤ 1) →
    ∀ s : Status, s = .U ∨ s = .D →
      0 < siteFunctional s (localProduct a) ∧ normSq (localMean s a) ≤ (3 / 5 : ℝ)^2) ∧
  {b : Vec3 | ∃ a : Fin 3 → UnitVector, localMean .U (fun j => (a j).val) = b} =
    {b : Vec3 | normSq b ≤ (3 / 5 : ℝ)^2}

def TorusKernelStatement : Prop :=
  ∀ L N : Size,
    (∀ e : Bond L N, (bondSites e).card = 2) ∧ Function.Injective (@bondSites L N) ∧
    (∀ x : Site L N, (torusNeighbours x).card = 4 ∧ x ∉ torusNeighbours x) ∧
    B L N ≠ 0 ∧ LinearMap.ker (H L N) = Submodule.span ℂ {B L N} ∧
    ∀ ε : Bond L N → Bool, Submodule.span ℂ {reorientedB L N ε} = Submodule.span ℂ {B L N}

def H1TheoremStatement : Prop :=
  ∀ π : PatternData, π.Covered → ∀ m : Fin 20 → UnitVector,
    (if π.outgoing = .north then (961 / 1000 : ℝ) else 187 / 200) * patternNext π m ≤ patternCurrent π m

def InputsStatement : Prop :=
  H1Statement ∧ H2Statement ∧ H3Statement ∧ certifiedRate < (2499 / 2500 : ℚ) ∧
    (2499 / 2500 : ℚ) < 1

def CutMOSStatement : Prop :=
  ∀ A θ : ℝ, ResponseProperty A θ →
    ∃ Mstar : ℕ, WindowProperty 64 (cutProbability A θ) Mstar
